#include <bits/stdc++.h>
using namespace std;
#define ll long long

ll f(vector<ll>& v, ll n, ll m){
    int l = v[0]-1;
    vector<ll> d;
    for(int i=0;i<m-1;i++) d.push_back(v[i+1]-v[i]-1);
    ll add = 0;
    for(int i=0;i<m-1;i++) add = max(add,d[i]-l);
    add = max(add,n-v.back());
    return l+l+add;
}

void solve(){
    ll n,m; cin >>n>>m;
    vector<ll> x(m);
    for(int i=0;i<m;i++) cin>>x[i];
    
    
    sort(x.begin(),x.end());
    ll ans = f(x,n,m);
    for(int i=0;i<m;i++) x[i] = n-x[i]+1;
    sort(x.begin(),x.end());
    // for(auto &i:x) cout<<i<<" ";
    // cout<<endl;
    cout<<min(ans,f(x,n,m))<<endl;
}




int main() {
	// your code goes here
	int t;cin>>t;
	while(t--) solve();
	return 0;

}
